PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "about_us_companymission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "mission" text NOT NULL, "vision" text NOT NULL);
CREATE TABLE IF NOT EXISTS "about_us_recentachievement" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(150) NOT NULL, "description" text NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "commentaries_commentaries" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(250) NOT NULL, "description" text NOT NULL);
CREATE TABLE IF NOT EXISTS "event_dialogue" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "date" date NULL, "title" varchar(150) NOT NULL, "venue" varchar(250) NULL, "organized_by" varchar(250) NULL, "chairperson" varchar(250) NOT NULL, "description" text NOT NULL, "chief_guest" varchar(250) NULL);
CREATE TABLE IF NOT EXISTS "event_othersite" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "site1" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "event_programschedule" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "start_time" varchar(50) NOT NULL, "end_time" varchar(50) NOT NULL, "title" varchar(255) NOT NULL, "description" text NOT NULL, "moderator" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "event_session" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "session_no" integer unsigned NOT NULL CHECK ("session_no" >= 0), "title" varchar(255) NOT NULL, "start_time" varchar(50) NOT NULL, "end_time" varchar(50) NOT NULL, "description" text NOT NULL, "Panelists" text NOT NULL, "moderator" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "event_video" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "youtube_url" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "event_program" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "category" varchar(100) NOT NULL, "image" varchar(100) NULL, "description" text NOT NULL, "objective" text NOT NULL, "participants" text NOT NULL, "expected_outcome" text NOT NULL, "date" varchar(100) NOT NULL, "status" varchar NOT NULL);
CREATE TABLE IF NOT EXISTS "homesection_sliderimage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "slider_id" bigint NOT NULL REFERENCES "homesection_slider" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "homesection_slider" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(250) NOT NULL, "description" text NOT NULL, "is_active" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "homesection_gallery" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "research_area_globalcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "category" varchar(250) NOT NULL);
CREATE TABLE IF NOT EXISTS "research_area_publicationtype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "category" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "research_area_theme" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "description" text NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "research_area_book" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "book" varchar(100) NULL, "author" varchar(255) NOT NULL, "book_cover" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "research_area_gloabalpower" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(250) NOT NULL, "description" text NULL, "category_id" bigint NOT NULL REFERENCES "research_area_globalcategory" ("id") DEFERRABLE INITIALLY DEFERRED, "pdf" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "research_area_publication" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "excerpt" text NOT NULL, "date" date NOT NULL, "created_at" datetime NOT NULL, "category_id" bigint NOT NULL REFERENCES "research_area_publicationtype" ("id") DEFERRABLE INITIALLY DEFERRED, "theme_id" bigint NOT NULL REFERENCES "research_area_theme" ("id") DEFERRABLE INITIALLY DEFERRED, "pdf" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "research_area_researchartical" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "Cover_image" varchar(100) NOT NULL, "title" varchar(250) NOT NULL, "description" text NULL, "file" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "event_programhighlight" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "program_id" bigint NOT NULL REFERENCES "event_program" ("id") DEFERRABLE INITIALLY DEFERRED, "text" varchar(255) NULL);
CREATE TABLE IF NOT EXISTS "home_section_highlightsection" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "tagline" varchar(255) NOT NULL, "description" text NOT NULL, "button_text" varchar(100) NOT NULL, "button_url" varchar(200) NOT NULL, "slide_image_1" varchar(100) NOT NULL, "slide_image_2" varchar(100) NOT NULL, "slide_image_3" varchar(100) NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "home_section_session" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "subtitle" varchar(255) NOT NULL, "image" varchar(100) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "highlight_id" bigint NOT NULL REFERENCES "home_section_highlightsection" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
