INSERT INTO event_program VALUES(1,'The Himalayan Dialogue','Flagship Program','programs/chairman.png','A premier strategic dialogue platform bringing together policymakers, diplomats, scholars, and business leaders to discuss regional and global issues through a Himalayan lens.','','','','','current');
INSERT INTO event_program VALUES(2,'South Asia Strategic Forum 2026','','','The South Asia Strategic Forum will convene policymakers, diplomats, scholars, and business leaders to discuss the evolving geopolitical and economic landscape of South Asia. The forum will explore regional connectivity, strategic competition, economic integration, and opportunities for cooperative security.','Promote strategic dialogue and policy collaboration across South Asia.','Government officials, diplomats, academics, business leaders, and regional experts.','Policy recommendations and strengthened regional partnerships.','March 2026','upcoming');
INSERT INTO event_program VALUES(3,'Climate Diplomacy Summit','','','The summit will focus on climate resilience, Himalayan sustainability, and international climate negotiations. It aims to amplify mountain-state perspectives within global climate governance discussions.','Strengthen climate diplomacy and regional cooperation.','Climate experts, policymakers, development partners, and researchers.','Regional climate policy roadmap and collaborative initiatives.','June 2026','upcoming');
